const todayLocal=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
const localISO=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const person=()=>escapeHTML(state.profile.name||'Anushka');
const originalSave=save;save=function(){if(quiz?.mode==='test'){try{sessionStorage.setItem('catalyst-active-test',JSON.stringify(quiz))}catch{}}originalSave()};
const addedNav=[['schedule','▦','Daily schedule'],['timer','◴','Study timer'],['calculator','⊞','Calculator'],['notebook','▱','My notebook'],['references','↗','Reference shelf'],['settings','⚙','My preferences']];
$('#nav').innerHTML+=`<div class="nav-divider">MADE FOR YOU</div>`+addedNav.map(([id,icon,label])=>`<a href="#${id}" data-nav="${id}"><span class="icon">${icon}</span>${label}</a>`).join('');
$('.settings').textContent='ⓘ  Exam guide & MBA checklist';
function daysBetween(a,b){return Math.round((new Date(b+'T12:00:00')-new Date(a+'T12:00:00'))/86400000)}
function defaultPlan(){return {start:examPlanStart(),target:CAT_EXAM_DATE,minutes:state.profile.daily,created:Date.now(),generated:false,examPlan:true}}
function ensurePlan(){return alignPlanForExam()}
function phaseFor(date){const p=ensurePlan(),all=Math.max(1,daysBetween(p.start,p.target)+1),index=Math.max(0,daysBetween(p.start,date)),ratio=index/all;return {index,ratio,name:ratio<.4?'Foundation':ratio<.75?'Practice & connect':'Mock & refine',length:all}}
function dailyPlan(date){const p=ensurePlan(),phase=phaseFor(date),d=new Date(date+'T12:00:00'),rest=d.getDay()===Number(state.profile.restDay),minutes=p.minutes;
 if(rest)return [{id:'reflect',title:'Weekly reflection & gentle revision',desc:'Review your error notebook. Note one win, one recurring error, and one adjustment for next week.',minutes:Math.max(15,Math.round(minutes*.2)),section:'Review',link:'progress'},{id:'reset',title:'Rest, reset & prepare tomorrow',desc:'Keep today light. Choose tomorrow’s materials, then step away and recharge.',minutes:10,section:'Wellbeing',link:'schedule'}];
 const studyIndex=phase.index-Math.floor(phase.index/7),qaLessons=lessons.filter(l=>l.subject==='qa'),vLessons=lessons.filter(l=>l.subject==='varc'),dLessons=lessons.filter(l=>l.subject==='dilr'),qa=qaLessons[studyIndex%qaLessons.length],v=vLessons[Math.floor(studyIndex/2)%vLessons.length],dl=dLessons[studyIndex%dLessons.length];
 const reading=Math.max(10,Math.round(minutes*.15)),review=Math.max(10,Math.round(minutes*.15)),qaM=Math.round((minutes-reading-review)*.4),varcM=Math.round((minutes-reading-review)*.3),dilrM=minutes-reading-review-qaM-varcM;
 if(phase.ratio>=.75&&d.getDay()===6)return [{id:'mock',title:minutes>=120?'Full-length practice mock':'Timed sectional practice',desc:minutes>=120?'Sit for a 120-minute, three-section practice mock. Keep interruptions off.':'Take one 40-minute section. Use the rest of your session to understand the errors.',minutes:minutes>=120?120:40,section:'Mock',link:'tests'},{id:'mock-review',title:'Review the decisions, not just the score',desc:'Log skipped opportunities, time sinks, concept gaps and lucky guesses. If the mock uses today’s full budget, do this tomorrow.',minutes:Math.max(20,minutes-120),section:'Review',link:'progress'}];
 return [{id:'read',title:'Read, then explain it in your own words',desc:'Choose a substantial article. Write its central claim, paragraph roles and one qualified inference in your notebook.',minutes:reading,section:'VARC',link:'notebook'}, {id:'qa',title:(phase.ratio<.4?'Learn: ':'Practice: ')+qa.title,desc:phase.ratio<.4?'Study the concept and worked example. Solve 3–5 questions slowly, explaining every step.':'Attempt a focused question set. Check the method before increasing speed.',minutes:qaM,section:'QA',lesson:qa.id,link:'learn/qa'}, {id:'varc',title:v.title,desc:phase.ratio<.4?'Read the strategy guide. Apply it to one passage or verbal drill.':'Attempt a timed passage group, then eliminate each wrong option with evidence.',minutes:varcM,section:'VARC',lesson:v.id,link:'practice'}, {id:'dilr',title:dl.title,desc:'Represent a complete set using a table or diagram. Verify every clue, then review a more efficient route.',minutes:dilrM,section:'DILR',lesson:dl.id,link:'practice'}, {id:'review',title:'Close the loop: revise & log mistakes',desc:'Record one error and its cause, revisit an older mistake, and write tomorrow’s first action.',minutes:review,section:'Review',link:'notebook'}]}
renderDashboard=function(){oldDashboard();$('.page-heading h1').innerHTML=`${person()}, your dream deserves a plan <span style="font-size:23px">🌤️</span>`;$('.page-heading p').textContent='Your own little corner of the internet. Built for your CAT journey.';$('.hero h2').innerHTML='For Anushka.<br>For everything she can become.'.replace('Anushka',person());$('.hero p').innerHTML=`Your lessons, your schedule, your progress.<br>No comparison. Just your next small step.`;$('.hero .primary').href='#schedule';$('.hero .primary').innerHTML='Open my day <span>↗</span>';$('.section-title h2').textContent='Your syllabus, one clear concept at a time';
 const oldTasks=$('.lower-grid .panel');const tasks=dailyPlan(todayLocal()),done=tasks.filter(t=>state.dailyTasks[todayLocal()+':'+t.id]).length;oldTasks.innerHTML=`<div class="section-title"><div><h2>Your day, made manageable</h2><p>${done}/${tasks.length} little steps complete</p></div><a href="#schedule">Full schedule →</a></div>${tasks.slice(0,3).map(t=>`<label class="task"><input type="checkbox" data-daily-check="${t.id}" ${state.dailyTasks[todayLocal()+':'+t.id]?'checked':''}><div><b>${t.title}</b><p>${t.minutes} min · ${t.section}</p></div></label>`).join('')}<a class="text-button" style="display:block;margin-top:15px" href="#schedule">See all tasks & time blocks →</a>`;document.querySelectorAll('[data-daily-check]').forEach(e=>e.onchange=()=>{state.dailyTasks[todayLocal()+':'+e.dataset.dailyCheck]=e.checked;save()});$('.bottom-banner b').textContent=`${state.profile.name}, you don’t have to figure it all out today.`;};
renderLearn=function(filter){if(filter)learnFilter=filter;app.innerHTML=heading('ANUSHKA’S LEARNING LIBRARY','Understand it. Make it yours.',`${lessons.length} original concept guides, with worked examples and common traps.`)+`<input class="search" id="lessonSearch" placeholder="Search any topic: logs, RC, arrangements…" aria-label="Search lessons" value="${escapeHTML(search)}"><div class="filters">${[['all','All topics'],...subjects.map(s=>[s.id,s.short])].map(([id,label])=>`<button class="filter ${learnFilter===id?'active':''}" data-filter="${id}">${label}</button>`).join('')}</div><div id="lessonGrid" class="lesson-grid"></div>`;drawLessons();$('#lessonSearch').oninput=e=>{search=e.target.value;drawLessons()};document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>renderLearn(b.dataset.filter))};
openLesson=function(id){const l=lessons.find(x=>x.id===id);$('#modalContent').innerHTML=`<article class="article"><span class="pill">${l.subject.toUpperCase()} · CONCEPT & APPLICATION</span><h2>${l.title}</h2><p>${l.concept}</p><h3>Keep this in your toolkit</h3><div class="formula">${l.formula}</div><h3>A worked example</h3><p>${l.example}</p><h3>A common trap</h3><p>${l.trap}</p><h3>Make it stick</h3><p>Close this guide and explain the idea in your own words. Then try an application without looking at the formula.</p><div class="field"><label for="lessonNote">Your note on this topic</label><textarea id="lessonNote" placeholder="What clicked? What should future-you remember?">${escapeHTML(state.notes['lesson:'+id]||'')}</textarea></div><div class="quiz-actions"><button class="primary" id="completeLesson">${state.completed.includes(id)?'✓ Learned':'Mark as learned'}</button><button class="secondary" id="saveLessonNote">Save my note</button><button class="secondary" id="practiceLesson">Practice this topic →</button></div></article>`;$('#modal').showModal();$('#completeLesson').onclick=()=>{if(!state.completed.includes(id)){state.completed.push(id);save()}$('#completeLesson').textContent='✓ Learned';toast('Another idea made clearer, '+state.profile.name+'.')};$('#saveLessonNote').onclick=()=>{state.notes['lesson:'+id]=$('#lessonNote').value;save();toast('Your note is saved.')};$('#practiceLesson').onclick=()=>{$('#modal').close();startPractice(l.subject,Q.some(x=>x.topic===id)?id:null)}};
let practiceSubject='all',practiceDifficulty='all';
renderPractice=function(){app.innerHTML=heading('ANUSHKA’S PRACTICE ARENA','A little braver with every attempt.',`${Q.length} original questions, ${passages.length} reading passages, and ${new Set(Q.filter(q=>q.subject==='dilr'&&q.group).map(q=>q.group)).size} linked reasoning sets.`)+`<div class="subject-grid">${subjects.map(s=>`<article class="subject ${s.color}"><div class="subject-symbol">${s.icon}</div><h3>${s.name}</h3><p>${Q.filter(q=>q.subject===s.id).length} questions · solutions included</p><div class="quiz-actions"><button class="primary" data-practice="${s.id}">Start ${s.short} →</button></div></article>`).join('')}</div><section class="panel" style="margin-top:22px"><div class="section-title"><h2>Choose what you need today</h2></div><div class="form-row"><div class="field"><label for="topicSelect">Topic</label><select id="topicSelect"><option value="all">All topics</option>${lessons.filter(l=>Q.some(q=>q.topic===l.id)).map(l=>`<option value="${l.id}">${l.subject.toUpperCase()} · ${l.title}</option>`).join('')}</select></div><div class="field"><label for="levelSelect">Level</label><select id="levelSelect"><option value="all">All levels</option><option>Foundation</option><option>Intermediate</option></select></div><button class="primary" id="topicPractice">Build my practice →</button></div><div class="quiz-actions"><button class="secondary" id="mixedPractice">Mixed question session</button><button class="secondary" id="bookmarkedPractice">Saved questions (${state.bookmarks.length})</button><button class="secondary" id="mistakePractice">Revisit mistakes</button></div></section><div class="notice">Original learning material, not copied past CAT papers. Levels are editorial labels, not statistically calibrated difficulty. Linked passage and set questions retain their full source information.</div>`;document.querySelectorAll('[data-practice]').forEach(b=>b.onclick=()=>startPractice(b.dataset.practice));$('#topicPractice').onclick=()=>{const topic=$('#topicSelect').value,level=$('#levelSelect').value;startQuestionList(Q.filter(q=>(topic==='all'||q.topic===topic)&&(level==='all'||q.difficulty===level)))};$('#mixedPractice').onclick=()=>startQuestionList(Q);$('#bookmarkedPractice').onclick=()=>startQuestionList(Q.filter(q=>state.bookmarks.includes(q.id)));$('#mistakePractice').onclick=()=>startQuestionList(Q.filter(q=>state.attempts.some(a=>a.id===q.id&&!a.correct)))};
function startQuestionList(list){if(!list.length){toast('No matching questions yet. Try another filter or save a question first.');return}quiz={mode:'practice',questions:list,index:0,answers:{},checked:{},started:Date.now()};renderQuiz()}
startPractice=function(subject,topic){startQuestionList(Q.filter(q=>(!subject||q.subject===subject)&&(!topic||q.topic===topic)))};
function isCorrect(question,answer){return question.type==='tita'?String(answer).trim()!==''&&Number(answer)===Number(question.answer):Number(answer)===question.answer}
recordAttempt=function(question,answer,persistAttempt=true){state.attempts.push({id:question.id,subject:question.subject,topic:question.topic,correct:isCorrect(question,answer),answer,time:Date.now()});updateReviewPlan(question,answer);if(persistAttempt)save()};
function setCurrentAnswer(value){const question=quiz.questions[quiz.index];if(value==='')delete quiz.answers[question.id];else quiz.answers[question.id]=value;if(quiz.mode==='test')persistTest();const node=document.querySelector(`[data-jump="${quiz.index}"]`);node?.classList.toggle('answered',value!=='')}
function persistTest(){try{if(quiz?.mode==='test')sessionStorage.setItem('catalyst-active-test',JSON.stringify(quiz));else sessionStorage.removeItem('catalyst-active-test')}catch{}}
function testIndices(){return quiz.sections?quiz.questions.map((q,i)=>i).filter(i=>i>=quiz.sections[quiz.section].start&&i<quiz.sections[quiz.section].end):quiz.questions.map((_,i)=>i)}
renderQuiz=function(){if(!quiz)return;const question=quiz.questions[quiz.index],a=quiz.answers[question.id],checked=quiz.checked[question.id],indices=testIndices();const topic=lessons.find(l=>l.id===question.topic)?.title||question.topic;
 app.innerHTML=heading(quiz.mode==='test'?'ANUSHKA’S TEST ROOM':'ANUSHKA’S PRACTICE DESK',quiz.mode==='test'?quiz.title:'Think it through. You have room to grow.',quiz.mode==='test'?'Stay with this question. The clock is handled for you.':'Read carefully, try honestly, then learn from the explanation.')+`${quiz.sections?`<div class="section-tabs">${quiz.sections.map((s,i)=>`<span class="${i===quiz.section?'active':''}">${s.name} ${i<quiz.section?'✓':i>quiz.section?'⌑':''}</span>`).join('')}</div>`:''}<div class="quiz-layout ${question.passage?'with-passage':''}">${question.passage?`<section class="panel passage"><span class="pill">${question.subject==='varc'?'READING PASSAGE':'SHARED SET'} · ${question.groupTitle}</span><div class="passage-text">${escapeHTML(question.passage)}</div></section>`:''}<section class="question-card"><div class="section-title"><span class="pill">${question.subject.toUpperCase()} · ${quiz.index+1}/${quiz.questions.length} · ${question.type==='tita'?'TITA':'MCQ'}</span><button class="text-button" id="bookmarkQuestion" aria-label="${state.bookmarks.includes(question.id)?'Unsave':'Save'} question">${state.bookmarks.includes(question.id)?'★ Saved':'☆ Save'}</button></div><p class="muted">${topic} · ${question.difficulty}</p><h2>${escapeHTML(question.text)}</h2>${question.type==='tita'?`<div class="field"><label for="numericAnswer">Type your numerical answer (no options)</label><input id="numericAnswer" type="number" step="any" placeholder="Your answer" value="${a===undefined?'':escapeHTML(a)}" ${checked?'disabled':''}></div>`:question.options.map((o,i)=>`<label class="option ${checked?(i===question.answer?'correct':i===Number(a)?'wrong':''):''}"><input type="radio" name="answer" value="${i}" ${Number(a)===i&&a!==undefined?'checked':''} ${checked?'disabled':''}><span>${String.fromCharCode(65+i)}.</span><span>${escapeHTML(o)}</span></label>`).join('')}${checked?`<div class="explanation"><b>${isCorrect(question,a)?'✓ You’ve got it.':'A mistake worth learning from.'}</b><br>${question.type==='tita'?'Correct answer: '+question.answer+'<br>':''}${question.explanation}</div><div class="confidence-row"><label for="errorCause">${isCorrect(question,a)?'How did it feel?':'What caused the miss?'}</label><select id="errorCause"><option value="">Choose a reflection…</option>${['Clear understanding','Lucky guess','Concept gap','Misread the question','Calculation error','Time pressure','Wrong set selection'].map(x=>`<option ${state.confidence[question.id]===x?'selected':''}>${x}</option>`).join('')}</select></div>`:''}<div class="quiz-actions">${quiz.mode==='practice'&&!checked?'<button class="primary" id="checkAnswer">Check answer →</button>':''}<button class="secondary" id="prevQ" ${quiz.index===indices[0]?'disabled':''}>← Previous</button><button class="${checked?'primary':'secondary'}" id="nextQ">${quiz.index===indices[indices.length-1]?(quiz.mode==='test'?'Section summary':'Finish session'):'Next →'}</button>${quiz.mode==='test'?'<button class="secondary" id="clearAnswer">Clear</button><button class="secondary" id="markReview">'+(quiz.flagged?.includes(question.id)?'⚑ Marked':'⚑ Review')+'</button>':'<button class="text-button" id="exitPractice">End practice</button>'}</div></section><aside><div class="panel">${quiz.mode==='test'?'<span class="eyebrow">'+(quiz.sections?'SECTION ':'')+'TIME LEFT</span><div class="timer" id="testTimer"></div>':'<h3 style="font-size:14px">Your question map</h3>'}<div class="question-map">${indices.map(i=>{const x=quiz.questions[i];return `<button class="${i===quiz.index?'current':''} ${quiz.answers[x.id]!==undefined?'answered':''} ${quiz.flagged?.includes(x.id)?'flagged':''}" data-jump="${i}" aria-label="Go to question ${i+1}">${i+1}</button>`}).join('')}</div><p class="muted">Green: answered · Dot: review<br>${quiz.mode==='test'?'+3 correct · −1 incorrect MCQ<br>TITA and unanswered: no penalty':'Check an answer to save the attempt.'}</p>${quiz.mode==='test'?'<button class="primary" id="submitTest">'+(quiz.sections&&quiz.section<2?'Finish section':'Submit test')+'</button>':''}</div></aside></div>`;
 if($('#numericAnswer'))$('#numericAnswer').oninput=e=>setCurrentAnswer(e.target.value);document.querySelectorAll('input[name=answer]').forEach(e=>e.onchange=()=>setCurrentAnswer(Number(e.value)));document.querySelectorAll('[data-jump]').forEach(b=>b.onclick=()=>{quiz.index=Number(b.dataset.jump);persistTest();renderQuiz()});$('#prevQ').onclick=()=>{if(quiz.index>indices[0]){quiz.index--;persistTest();renderQuiz()}};$('#nextQ').onclick=()=>{if(quiz.index<indices[indices.length-1]){quiz.index++;persistTest();renderQuiz()}else quiz.mode==='test'?confirmTest():finishPractice()};$('#bookmarkQuestion').onclick=()=>{state.bookmarks=state.bookmarks.includes(question.id)?state.bookmarks.filter(x=>x!==question.id):[...state.bookmarks,question.id];save();$('#bookmarkQuestion').textContent=state.bookmarks.includes(question.id)?'★ Saved':'☆ Save';toast(state.bookmarks.includes(question.id)?'Saved for another look.':'Removed from saved questions.')};if($('#checkAnswer'))$('#checkAnswer').onclick=()=>{if(quiz.answers[question.id]===undefined){toast('Try an answer first.');return}quiz.checked[question.id]=true;recordAttempt(question,quiz.answers[question.id]);renderQuiz()};if($('#errorCause'))$('#errorCause').onchange=e=>{state.confidence[question.id]=e.target.value;adjustReviewReflection(question.id,e.target.value);save()};if($('#exitPractice'))$('#exitPractice').onclick=finishPractice;if($('#clearAnswer'))$('#clearAnswer').onclick=()=>{delete quiz.answers[question.id];persistTest();renderQuiz()};if($('#markReview'))$('#markReview').onclick=()=>{quiz.flagged??=[];quiz.flagged=quiz.flagged.includes(question.id)?quiz.flagged.filter(x=>x!==question.id):[...quiz.flagged,question.id];persistTest();renderQuiz()};if($('#submitTest'))$('#submitTest').onclick=confirmTest;updateTestTimer();
};
finishPractice=function(){const count=Object.keys(quiz.checked).length,correct=quiz.questions.filter(q=>quiz.checked[q.id]&&isCorrect(q,quiz.answers[q.id])).length;quiz=null;app.innerHTML=heading('A STEP WORTH TAKING',`Good work, ${person()}.`,'The important part is what you take into the next attempt.')+`<section class="panel result"><div class="score">${correct}<span style="font-size:25px"> / ${count}</span></div><p>Checked answers correct. Skipped and unchecked answers were not scored.<br>Come back to the saved questions and error notebook whenever you need.</p><button class="primary" id="morePractice">Back to practice →</button> <a class="secondary" href="#progress">My progress</a></section>`;$('#morePractice').onclick=renderPractice};
function pickQuestions(subject,count){const list=Q.filter(q=>q.subject===subject);if(subject==='qa')return shuffle(list).slice(0,count);let remaining=count,chosen=[],groups=[...new Set(list.filter(q=>q.group).map(q=>q.group))];for(const group of shuffle(groups)){if(remaining<=0)break;const set=list.filter(q=>q.group===group);const n=Math.min(set.length,remaining);chosen.push(...set.slice(0,n));remaining-=n;if(subject==='varc'&&chosen.length>=16)break}if(remaining)chosen.push(...shuffle(list.filter(q=>!q.group&&!chosen.includes(q))).slice(0,remaining));return chosen.slice(0,count)}
function shuffle(a){const x=[...a];for(let i=x.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[x[i],x[j]]=[x[j],x[i]]}return x}
renderTests=function(){app.innerHTML=heading('ANUSHKA’S TEST ROOM','Practice the calm, too.','From a first diagnostic to a complete three-section sitting.')+`<section class="full-mock"><div><span class="eyebrow">YOUR NEXT MILESTONE</span><h2>A full-length practice sitting</h2><p>68 questions · 120 minutes · Three locked 40-minute sections<br>VARC 24 → DILR 22 → QA 22 · MCQ + numerical entry</p><button class="primary" id="fullMock">Begin full practice mock →</button></div><span class="mock-art" aria-hidden="true">120<small>minutes of showing up</small></span></section><div class="test-grid" style="margin-top:20px">${subjects.map(s=>`<article class="test-card"><div class="subject-symbol">${s.icon}</div><h3>${s.short} sectional</h3><p>${s.id==='varc'?24:22} questions · 40 minutes<br>Shared passages and sets stay together.<br>Detailed answer review after submission.</p><button class="primary" data-sectional="${s.id}">Start ${s.short} →</button></article>`).join('')}</div><section class="panel" style="margin-top:20px"><div class="section-title"><div><h2>Not sure where to start?</h2><p>A 12-question, 24-minute diagnostic across all sections.</p></div><button class="primary" id="diagnostic">Find my starting point →</button></div><p class="muted">It gives a small sample of strengths and gaps, not a predicted CAT percentile.</p></section><div class="notice">The 68-question format is a configurable practice template based on a recent exam structure, not a verified current-year CAT specification. Content is original, editorially leveled and reused from the practice library. It is not an official paper or a calibrated coaching mock. You can end a section early, but cannot return after confirming. Reloading this tab resumes the test; closing the tab can discard an unfinished test.</div>`;$('#fullMock').onclick=()=>startTimedTest('full');document.querySelectorAll('[data-sectional]').forEach(b=>b.onclick=()=>startTimedTest(b.dataset.sectional));$('#diagnostic').onclick=()=>startTimedTest('diagnostic')};
function startTimedTest(kind){const full=kind==='full',diagnostic=kind==='diagnostic';let questions,sections=null;if(full){const v=pickQuestions('varc',24),d=pickQuestions('dilr',22),a=pickQuestions('qa',22);questions=[...v,...d,...a];sections=[{name:'VARC',start:0,end:24},{name:'DILR',start:24,end:46},{name:'QA',start:46,end:68}]}else questions=diagnostic?[...pickQuestions('varc',4),...pickQuestions('dilr',4),...pickQuestions('qa',4)]:pickQuestions(kind,kind==='varc'?24:22);quiz={mode:'test',kind,title:full?'Anushka’s full-length practice':diagnostic?'Find your starting point':kind.toUpperCase()+' sectional practice',questions,sections,section:0,index:0,answers:{},checked:{},flagged:[],started:Date.now(),ends:Date.now()+(diagnostic?24:40)*60000};persistTest();clearInterval(quizTimer);quizTimer=setInterval(updateTestTimer,1000);renderQuiz()}
confirmTest=function(){const indices=testIndices(),unanswered=indices.filter(i=>quiz.answers[quiz.questions[i].id]===undefined).length,more=quiz.sections&&quiz.section<2;$('#modalContent').innerHTML=`<div class="article"><h2>${more?'Finish this section?':'Ready to submit?'}</h2><p>${unanswered} unanswered question${unanswered===1?'':'s'} in this ${quiz.sections?'section':'test'}.${more?' Once confirmed, this section locks and the next 40-minute section begins. You cannot return.':' Your results and explanations will be ready immediately.'}</p><button class="primary" id="confirmSubmit">${more?'Lock section & continue →':'Submit & review →'}</button></div>`;$('#modal').showModal();$('#confirmSubmit').onclick=()=>{$('#modal').close();advanceTest()}};
function advanceTest(automatic=false){if(quiz.sections&&quiz.section<2){const nextDeadline=(automatic?quiz.ends:Date.now())+40*60000;quiz.section++;quiz.index=quiz.sections[quiz.section].start;quiz.ends=nextDeadline;persistTest();renderQuiz();toast('A fresh section. Take a breath.')}else finishTest()}
updateTestTimer=function(){if(!quiz||quiz.mode!=='test')return;const seconds=Math.max(0,Math.ceil((quiz.ends-Date.now())/1000));if($('#testTimer'))$('#testTimer').textContent=String(Math.floor(seconds/60)).padStart(2,'0')+':'+String(seconds%60).padStart(2,'0');if(!seconds){if($('#modal').open)$('#modal').close();advanceTest(true)}};
finishTest=function(){clearInterval(quizTimer);if(!quiz)return;const run=quiz;quiz=null;persistTest();let correct=0,wrong=0,penalty=0;run.questions.forEach(q=>{if(run.answers[q.id]!==undefined){recordAttempt(q,run.answers[q.id],false);if(isCorrect(q,run.answers[q.id]))correct++;else{wrong++;if(q.type!=='tita')penalty++}}});const result={title:run.title,time:Date.now(),correct,wrong,total:run.questions.length,score:correct*3-penalty,kind:run.kind,paperId:run.paperId,seconds:Math.round((Date.now()-run.started)/1000)};captureTestReview(run,result);state.results.push(result);save();app.innerHTML=heading('ANUSHKA’S NEXT CLUE','The score is a starting point.','Keep what worked. Understand what didn’t. Make the next attempt better.')+`<section class="panel result"><span class="eyebrow">${run.title}</span><div class="score">${result.score}<span style="font-size:22px"> / ${result.total*3}</span></div><p>${correct} correct · ${wrong} incorrect · ${result.total-correct-wrong} unanswered<br>+3 correct, −1 incorrect MCQ, no penalty for TITA. No percentile estimated.</p><button class="primary" id="anotherTest">Back to tests →</button></section><div class="subject-grid" style="margin-top:20px">${subjects.filter(s=>run.questions.some(q=>q.subject===s.id)).map(s=>{const a=run.questions.filter(q=>q.subject===s.id),right=a.filter(q=>run.answers[q.id]!==undefined&&isCorrect(q,run.answers[q.id])).length,attempted=a.filter(q=>run.answers[q.id]!==undefined).length;return `<section class="panel"><span class="pill">${s.short}</span><h3>${right}/${a.length} correct</h3><p class="muted">${attempted} attempted. ${right/a.length<.5?'Revisit concepts and review selection.':'Build on this with careful timed practice.'}</p></section>`}).join('')}</div><h3 style="margin-top:28px">Your complete answer review</h3>${run.questions.map((q,i)=>`<section class="panel article" style="margin:15px 0"><span class="pill">${i+1} · ${q.subject.toUpperCase()} · ${run.answers[q.id]===undefined?'UNANSWERED':isCorrect(q,run.answers[q.id])?'CORRECT':'INCORRECT'}</span>${q.passage?`<details><summary>${q.groupTitle} · Read the shared passage</summary><p style="white-space:pre-line">${escapeHTML(q.passage)}</p></details>`:''}<p style="white-space:pre-line">${escapeHTML(q.text)}</p><p>Your answer: <b>${run.answers[q.id]===undefined?'—':escapeHTML(q.type==='tita'?run.answers[q.id]:q.options[run.answers[q.id]])}</b><br>Correct answer: <b>${escapeHTML(q.type==='tita'?q.answer:q.options[q.answer])}</b></p><div class="explanation">${q.explanation}</div><button class="text-button" data-save-result="${q.id}">${state.bookmarks.includes(q.id)?'★ Saved':'☆ Save for revision'}</button></section>`).join('')}`;$('#anotherTest').onclick=renderTests;document.querySelectorAll('[data-save-result]').forEach(b=>b.onclick=()=>{const id=Number(b.dataset.saveResult);if(!state.bookmarks.includes(id)){state.bookmarks.push(id);save()}b.textContent='★ Saved'});window.scrollTo(0,0)};
let selectedScheduleDay=todayLocal();
function timePlus(time,minutes){const [h,m]=time.split(':').map(Number),total=h*60+m+minutes;return `${String(Math.floor(total/60)%24).padStart(2,'0')}:${String(total%60).padStart(2,'0')}`}
function formattedDate(date){return new Date(date+'T12:00:00').toLocaleDateString('en-IN',{weekday:'long',day:'numeric',month:'long',year:'numeric'})}
function renderSchedule(){const p=ensurePlan(),date=selectedScheduleDay,phase=phaseFor(date),outside=date<p.start||date>p.target,tasks=outside?[]:dailyPlan(date),done=tasks.filter(t=>state.dailyTasks[date+':'+t.id]).length;let elapsed=0;
 app.innerHTML=heading('A PLAN MADE FOR ANUSHKA','Just today’s little steps.',`${formattedDate(date)} · ${outside?'Outside your current plan':phase.name+' phase'}`,`<a href="#planner" class="secondary">Adjust my plan</a>`)+`<div class="schedule-hero"><div><span class="eyebrow">${p.generated?'YOUR EDITABLE 180-DAY STARTER PLAN':'YOUR PERSONAL ROADMAP'}</span><h2>${person()}, consistency can be gentle.</h2><p>${p.minutes} minutes on study days · ${['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'][state.profile.restDay]} is your lighter day.<br>${p.generated?'This is a starting template, not an assumed exam date. Change the target whenever you’re ready.':'Your target: '+formattedDate(p.target)}</p></div><div class="day-ring" style="--done:${tasks.length?done/tasks.length*100:0}%"><b>${done}/${tasks.length}</b><small>steps complete</small></div></div><div class="calendar-bar"><button class="secondary" id="prevDay">← Previous</button><input type="date" id="scheduleDate" aria-label="Schedule date" value="${date}"><button class="secondary" id="nextDay">Next →</button><button class="text-button" id="todaySchedule">Today</button><button class="text-button" id="calendarExport">Export 7 days (.ics) ↓</button></div><div class="week-strip">${Array.from({length:7},(_,i)=>{const d=new Date(date+'T12:00:00');d.setDate(d.getDate()-d.getDay()+i);const iso=localISO(d);return `<button data-date="${iso}" class="${iso===date?'active':''}"><small>${d.toLocaleDateString('en-IN',{weekday:'short'})}</small><b>${d.getDate()}</b><span>${iso===todayLocal()?'today':'·'}</span></button>`}).join('')}</div><div class="schedule-list">${tasks.length?tasks.map((t,i)=>{const start=timePlus(state.profile.startTime,elapsed),end=timePlus(state.profile.startTime,elapsed+t.minutes);elapsed+=t.minutes+5;const checked=state.dailyTasks[date+':'+t.id];return `<article class="schedule-task ${checked?'complete':''}"><div class="time-block"><b>${start}</b><span>${end}</span></div><label class="task-check"><input type="checkbox" data-plan-check="${t.id}" ${checked?'checked':''} aria-label="Complete ${escapeHTML(t.title)}"></label><div class="schedule-task-content"><span class="pill">${t.section} · ${t.minutes} MIN</span><h3>${t.title}</h3><p>${t.desc}</p><div class="quiz-actions">${t.paperNumber?`<button class="text-button" data-planned-mock="${t.paperNumber}">Start Full Mock ${t.paperNumber} →</button>`:t.lesson?`<button class="text-button" data-plan-lesson="${t.lesson}">Open lesson →</button>`:`<a class="text-button" href="#${t.link}">Open ${t.section==='Mock'?'test room':t.id==='read'?'notebook':'workspace'} →</a>`}${t.untimed?'':`<button class="text-button" data-task-timer="${t.minutes}" data-timer-label="${escapeHTML(t.title)}">◴ Start ${t.minutes}-min timer</button>`}</div></div></article>`}).join(''):'<div class="empty"><h2>A clear space.</h2><p>This date is outside your plan. Adjust the target or return to today.</p></div>'}</div><div class="notice">Five-minute transition breaks are placed between blocks. Times use your browser’s local clock and your chosen start time. Tasks are suggested, not automatically verified by visiting a page. Tick them when you finish. Missed days do not erase your progress; pick up with today.</div><section class="panel"><div class="section-title"><h2>A note for today’s version of you</h2></div><textarea id="dailyNote" placeholder="What went well? What felt difficult? What’s one small thing for tomorrow?">${escapeHTML(state.notes['day:'+date]||'')}</textarea><button class="primary" id="saveDailyNote" style="margin-top:12px">Save today’s note ♡</button></section>`;
 $('#prevDay').onclick=()=>shiftSchedule(-1);$('#nextDay').onclick=()=>shiftSchedule(1);$('#scheduleDate').onchange=e=>{if(e.target.value){selectedScheduleDay=e.target.value;renderSchedule()}};$('#todaySchedule').onclick=()=>{selectedScheduleDay=todayLocal();renderSchedule()};document.querySelectorAll('[data-date]').forEach(b=>b.onclick=()=>{selectedScheduleDay=b.dataset.date;renderSchedule()});document.querySelectorAll('[data-plan-check]').forEach(e=>e.onchange=()=>{state.dailyTasks[date+':'+e.dataset.planCheck]=e.checked;save();renderSchedule()});document.querySelectorAll('[data-plan-lesson]').forEach(b=>b.onclick=()=>openLesson(b.dataset.planLesson));document.querySelectorAll('[data-task-timer]').forEach(b=>b.onclick=()=>{configureTimer(Number(b.dataset.taskTimer),b.dataset.timerLabel,'study');location.hash='timer';renderStudyTimer()});document.querySelectorAll('[data-planned-mock]').forEach(b=>b.onclick=()=>beginPaper(paperDefinition('full',Number(b.dataset.plannedMock))));$('#saveDailyNote').onclick=()=>{state.notes['day:'+date]=$('#dailyNote').value;save();toast('A little reflection, saved.')};$('#calendarExport').onclick=exportCalendar;
}
function shiftSchedule(n){const d=new Date(selectedScheduleDay+'T12:00:00');d.setDate(d.getDate()+n);selectedScheduleDay=localISO(d);renderSchedule()}
function icsEscape(s){return String(s).replace(/\\/g,'\\\\').replace(/\n/g,'\\n').replace(/,/g,'\\,').replace(/;/g,'\\;')}
function exportCalendar(){const p=ensurePlan(),lines=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//CATalyst//Anushka Study Plan//EN','CALSCALE:GREGORIAN'];let count=0;for(let i=0;i<7;i++){const d=new Date(selectedScheduleDay+'T12:00:00');d.setDate(d.getDate()+i);const date=localISO(d);if(date<p.start||date>p.target||date===CAT_EXAM_DATE)continue;let offset=0;dailyPlan(date).forEach(t=>{const start=new Date(date+'T'+state.profile.startTime+':00');start.setMinutes(start.getMinutes()+offset);const end=new Date(start.getTime()+t.minutes*60000);const stamp=x=>localISO(x).replace(/-/g,'')+'T'+String(x.getHours()).padStart(2,'0')+String(x.getMinutes()).padStart(2,'0')+'00';lines.push('BEGIN:VEVENT',`UID:catalyst-${date}-${t.id}@anushkadangwal.com`,`DTSTAMP:${new Date().toISOString().replace(/[-:]/g,'').replace(/\.\d+Z$/,'Z')}`,`DTSTART:${stamp(start)}`,`DTEND:${stamp(end)}`,`SUMMARY:${icsEscape('CAT · '+t.title)}`,`DESCRIPTION:${icsEscape(t.desc)}`,'END:VEVENT');offset+=t.minutes+5;count++})}lines.push('END:VCALENDAR');if(!count){toast('No study blocks in this week. Exam-day timing follows your admit card.');return}download('anushka-cat-study-week.ics',lines.join('\r\n')+'\r\n');toast('Calendar file exported. Import it into your calendar app.')}
renderPlanner=function(){const p=ensurePlan(),days=Math.max(0,daysBetween(todayLocal(),p.target)+1);app.innerHTML=heading('ANUSHKA’S PERSONAL ROADMAP','One dream. A plan that bends with life.','Build daily tasks from your target, study budget and lighter day.')+`<section class="panel"><div class="form-row"><div class="field"><label for="planStart">Plan begins</label><input id="planStart" type="date" value="${p.start}"></div><div class="field"><label for="targetDate">Target date / planning deadline</label><input id="targetDate" type="date" value="${p.target}"></div><div class="field"><label for="dailyMinutes">Daily study budget</label><select id="dailyMinutes">${[60,90,120,150,180,240,300].map(n=>`<option value="${n}" ${p.minutes===n?'selected':''}>${n} minutes</option>`).join('')}</select></div></div><div class="form-row" style="margin-top:18px"><div class="field"><label for="studyStart">Usual starting time</label><input id="studyStart" type="time" value="${state.profile.startTime}"></div><div class="field"><label for="lightDay">Weekly lighter day</label><select id="lightDay">${['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'].map((d,i)=>`<option value="${i}" ${Number(state.profile.restDay)===i?'selected':''}>${d}</option>`).join('')}</select></div><button id="makePlan" class="primary">Save my day-by-day plan →</button></div><p class="muted">${p.generated?'We started with an editable 180-day template. No CAT year or official exam date has been assumed.':'Your dates are personal planning choices; verify official CAT dates separately.'}</p></section><div class="roadmap-grid"><article><span>01</span><h3>Build the foundations</h3><p>First 40% of your plan. Learn concepts, read every day, and solve accurately before chasing speed.</p></article><article><span>02</span><h3>Connect & apply</h3><p>Next 35%. Mix topics, practice complete sets and passages, and revisit mistakes with a reason.</p></article><article><span>03</span><h3>Test & refine</h3><p>Final 25%. Weekly timed practice, careful analysis, revision and sustainable test-day habits.</p></article></div><section class="panel"><div class="section-title"><div><h2>${days} days to your planning target</h2><p>Daily reading + QA + VARC + DILR + review, with lighter days built in.</p></div><a href="#schedule" class="primary">Open my daily schedule →</a></div><p class="muted">This is an editable general roadmap, not an adaptive tutor. The diagnostic and error notebook help you decide where to shift effort. If you have under 120 minutes on a mock day, use a sectional instead of a full mock. A full mock may require analysis the following day.</p><button class="secondary" id="exportFullPlan">Download complete daily plan ↓</button></section>`;$('#makePlan').onclick=()=>{const start=$('#planStart').value,target=$('#targetDate').value,time=$('#studyStart').value;if(!start||!target||target<start||!time){toast('Enter a valid start date, later target date and study time.');return}if(daysBetween(start,target)>730){toast('Choose a planning window of two years or less.');return}state.plan={start,target,minutes:Number($('#dailyMinutes').value),created:Date.now(),generated:false};state.profile.daily=state.plan.minutes;state.profile.startTime=time;state.profile.restDay=Number($('#lightDay').value);save();selectedScheduleDay=todayLocal()<start?start:todayLocal()>target?target:todayLocal();renderPlanner();toast('Your daily plan is saved, '+state.profile.name+'.')};$('#exportFullPlan').onclick=()=>{const p=ensurePlan(),n=Math.min(731,daysBetween(p.start,p.target)+1);const out=[`${state.profile.name}’s CAT day-by-day plan`,`From ${p.start} to ${p.target}. ${p.minutes} minutes on study days.`,`Times use your local time zone; a 5-minute transition follows each block.`,`This is a personal plan, not an official exam schedule.\n`];for(let i=0;i<n;i++){const d=new Date(p.start+'T12:00:00');d.setDate(d.getDate()+i);const date=localISO(d);out.push(formattedDate(date)+' — '+phaseFor(date).name);let offset=0;dailyPlan(date).forEach(t=>{out.push(`${timePlus(state.profile.startTime,offset)} | ${t.minutes} min | ${t.title}\n  ${t.desc}`);offset+=t.minutes+5});out.push('')}download('anushka-complete-cat-plan.txt',out.join('\n'))}}
// A refresh-safe countdown: remaining time derives from a stored deadline, never interval counts.
let studyClock=state.studyClock||{duration:1500,remaining:1500,running:false,end:null,label:'One focused step',kind:'study'};
let studyTicker=null;
function persistClock(){state.studyClock=studyClock;originalSave()}
function remainingSeconds(){return studyClock.running?Math.max(0,Math.ceil((studyClock.end-Date.now())/1000)):studyClock.remaining}
function settleClock(){if(studyClock.running&&remainingSeconds()===0){studyClock.running=false;studyClock.remaining=0;studyClock.end=null;if(studyClock.kind==='study')state.focus+=Math.floor(studyClock.duration/60);persistClock();toast(studyClock.kind==='break'?'Break complete. Come back gently.':'Session complete, '+state.profile.name+'. Your focus time is saved.');if(location.hash==='#timer')renderStudyTimer()}}
function configureTimer(minutes,label,kind){if(studyClock.running||studyClock.remaining<studyClock.duration&&studyClock.remaining>0){toast('Finish or reset your current timer before starting a new one.');return false}studyClock={duration:minutes*60,remaining:minutes*60,running:false,end:null,label,kind};persistClock();return true}
function clockDisplay(s){return `${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`}
function renderStudyTimer(){settleClock();app.innerHTML=heading('ANUSHKA’S QUIET CORNER','One thing at a time.','A timer for your study blocks, a little space for your mind.')+`<div class="timer-layout"><section class="focus-panel"><span class="eyebrow">${studyClock.kind==='break'?'A WELL-EARNED BREATHER':'YOUR NEXT SMALL STEP'}</span><h2>${escapeHTML(studyClock.label)}</h2><div class="big-clock" id="bigClock" role="timer" aria-label="Time remaining">${clockDisplay(remainingSeconds())}</div><p id="timerStatus">${studyClock.remaining===0?'Session complete. Choose your next step.':studyClock.running?'You don’t need to do everything. Just this.':'When you’re ready, press start.'}</p><div class="quiz-actions" style="justify-content:center"><button class="primary" id="startClock">${studyClock.running?'Pause':studyClock.remaining===0?'Start again':'Start focus'}</button><button class="secondary" id="resetClock">Reset</button><button class="secondary" id="endClock">Finish early & save</button></div><div class="timer-presets"><button data-clock-min="25">25 min focus</button><button data-clock-min="50">50 min deep work</button><button data-clock-min="5" data-break="true">5 min break</button><button data-clock-min="15" data-break="true">15 min break</button></div></section><section class="panel"><div class="section-title"><h2>Make this session yours</h2></div><div class="field"><label for="sessionLabel">What are you working on?</label><input id="sessionLabel" maxlength="90" value="${escapeHTML(studyClock.label)}" placeholder="e.g. Arithmetic revision"></div><div class="field" style="margin-top:18px"><label for="sessionMinutes">Duration (1–180 minutes)</label><input id="sessionMinutes" type="number" min="1" max="180" value="${Math.floor(studyClock.duration/60)}"></div><button class="primary" id="applyClock" style="margin-top:18px">Set my session →</button><p class="muted">The deadline survives a refresh in this browser. Keep one timer tab open. This is a quiet timer; there is no alarm or system notification. Breaks do not add study minutes. Reset discards elapsed time; Finish early saves completed study minutes.</p><div class="achievement">◷ &nbsp; ${state.focus} focused minutes saved so far</div><a class="text-button" href="#schedule" style="display:block;margin-top:18px">Back to my daily schedule →</a></section></div>`;
 $('#startClock').onclick=()=>{if(studyClock.running){studyClock.remaining=remainingSeconds();studyClock.running=false;studyClock.end=null}else{if(studyClock.remaining===0)studyClock.remaining=studyClock.duration;studyClock.end=Date.now()+studyClock.remaining*1000;studyClock.running=true}persistClock();renderStudyTimer()};$('#resetClock').onclick=()=>{if((studyClock.running||studyClock.remaining<studyClock.duration)&&!confirm('Reset this session? Unsaved elapsed time will be discarded.'))return;studyClock.remaining=studyClock.duration;studyClock.running=false;studyClock.end=null;persistClock();renderStudyTimer()};$('#endClock').onclick=()=>{const rem=remainingSeconds();if(studyClock.remaining===0){toast('This completed session is already saved.');return}const elapsed=studyClock.duration-rem;if(studyClock.kind==='study')state.focus+=Math.floor(elapsed/60);studyClock.running=false;studyClock.remaining=studyClock.duration;studyClock.end=null;persistClock();renderStudyTimer();toast('Saved '+(studyClock.kind==='study'?Math.floor(elapsed/60):0)+' completed study minutes.')};document.querySelectorAll('[data-clock-min]').forEach(b=>b.onclick=()=>{if(configureTimer(Number(b.dataset.clockMin),b.dataset.break?'A little breather':'One focused step',b.dataset.break?'break':'study'))renderStudyTimer()});$('#applyClock').onclick=()=>{const minutes=Number($('#sessionMinutes').value),label=$('#sessionLabel').value.trim();if(!Number.isInteger(minutes)||minutes<1||minutes>180){toast('Choose a whole number from 1 to 180 minutes.');return}if(configureTimer(minutes,label||'One focused step','study'))renderStudyTimer()}}
clearInterval(focusInterval);$('#focusButton').onclick=()=>{location.hash='timer';if(location.hash==='#timer')renderStudyTimer()};studyTicker=setInterval(()=>{settleClock();if($('#bigClock'))$('#bigClock').textContent=clockDisplay(remainingSeconds());$('#focusLabel').textContent=studyClock.running?clockDisplay(remainingSeconds()):'Study timer'},1000);
// Restricted arithmetic parser: no eval, Function constructor, or arbitrary JavaScript.
function calculateExpression(source){const input=source.replace(/×/g,'*').replace(/÷/g,'/').replace(/−/g,'-').replace(/\s/g,'');if(!input||input.length>160)throw Error('Enter an expression of up to 160 characters.');const tokens=input.match(/(?:\d*\.\d+|\d+\.?\d*)|[()+\-*/%]/g)||[];if(tokens.join('')!==input)throw Error('Use numbers, decimal points, parentheses and + − × ÷ %.');let at=0;function primary(){if(tokens[at]==='+'){at++;return primary()}if(tokens[at]==='-'){at++;return -primary()}let v;if(tokens[at]==='('){at++;v=expression();if(tokens[at++]!==')')throw Error('Check your parentheses.')}else{const token=tokens[at++];if(!token||!/^(\d*\.\d+|\d+\.?\d*)$/.test(token))throw Error('Enter a number here.');v=Number(token)}while(tokens[at]==='%'){v/=100;at++}return v}function term(){let v=primary();while(tokens[at]==='*'||tokens[at]==='/'){const op=tokens[at++],n=primary();if(op==='/'&&n===0)throw Error('Cannot divide by zero.');v=op==='*'?v*n:v/n}return v}function expression(){let v=term();while(tokens[at]==='+'||tokens[at]==='-'){const op=tokens[at++],n=term();v=op==='+'?v+n:v-n}return v}const result=expression();if(at!==tokens.length)throw Error('Check the operators and parentheses.');if(!Number.isFinite(result))throw Error('Result is outside the supported range.');return Number(result.toPrecision(12))}
let calcExpression='',calcHistory=[];
function renderCalculator(){app.innerHTML=heading('A LITTLE HELP WITH THE NUMBERS','Clear thinking, clear calculations.','A practice calculator and everyday arithmetic helpers.')+`<div class="calculator-layout"><section class="calculator panel"><div class="section-title"><h2>Your calculator</h2><span class="pill">PRACTICE TOOL</span></div><label class="muted" for="calcInput">Type an expression or use the keys</label><input id="calcInput" class="calc-display" inputmode="decimal" autocomplete="off" maxlength="160" value="${escapeHTML(calcExpression)}" placeholder="0"><div id="calcResult" class="calc-result" role="status">Ready when you are.</div><div class="calc-keys">${['C','(',')','⌫','7','8','9','÷','4','5','6','×','1','2','3','−','0','.','%','+'].map(x=>`<button data-calc="${x}" class="${['÷','×','−','+'].includes(x)?'operator':''}">${x}</button>`).join('')}<button id="calcEquals" class="equals">=</button></div><div class="calc-history" id="calcHistory"></div></section><div><section class="panel"><div class="section-title"><h2>Percentage change</h2></div><div class="form-row"><div class="field"><label for="oldValue">Original value</label><input type="number" id="oldValue" step="any"></div><div class="field"><label for="newValue">New value</label><input type="number" id="newValue" step="any"></div></div><button class="secondary" id="percentCalc" style="margin-top:15px">Find the change</button><p id="percentResult" class="helper-result" role="status">(new − original) ÷ original × 100</p></section><section class="panel" style="margin-top:20px"><div class="section-title"><h2>Average calculator</h2></div><div class="field"><label for="averageValues">Numbers separated by commas</label><input id="averageValues" placeholder="e.g. 12, 18, 24"></div><button class="secondary" id="averageCalc" style="margin-top:15px">Find the mean</button><p id="averageResult" class="helper-result" role="status">Sum of values ÷ number of values</p></section><div class="notice">Percentage key means “divide this number by 100”: 200×10% = 20; 200+10% = 200.1. Use 200×(1+10%) for a 10% increase. This tool is not a replica of the official CAT calculator. Use it to check work after trying mentally.</div></div></div>`;
 function evaluate(){calcExpression=$('#calcInput').value;try{const result=calculateExpression(calcExpression);$('#calcResult').textContent='= '+result;calcHistory.unshift({expression:calcExpression,result});calcHistory=calcHistory.slice(0,5);drawCalcHistory()}catch(e){$('#calcResult').textContent=e.message}}
 function drawCalcHistory(){$('#calcHistory').innerHTML=calcHistory.map((x,i)=>`<button data-history="${i}">${escapeHTML(x.expression)} <b>= ${x.result}</b></button>`).join('');document.querySelectorAll('[data-history]').forEach(b=>b.onclick=()=>{$('#calcInput').value=String(calcHistory[Number(b.dataset.history)].result)})}drawCalcHistory();$('#calcInput').oninput=e=>calcExpression=e.target.value;$('#calcInput').onkeydown=e=>{if(e.key==='Enter')evaluate()};document.querySelectorAll('[data-calc]').forEach(b=>b.onclick=()=>{const key=b.dataset.calc,input=$('#calcInput');if(key==='C'){input.value='';$('#calcResult').textContent='Ready when you are.'}else if(key==='⌫')input.value=input.value.slice(0,-1);else input.value+=key;calcExpression=input.value;input.focus()});$('#calcEquals').onclick=evaluate;$('#percentCalc').onclick=()=>{const a=$('#oldValue').value,b=$('#newValue').value;if(a===''||b===''||!Number.isFinite(Number(a))||!Number.isFinite(Number(b))||Number(a)<=0){$('#percentResult').textContent='Enter a positive original value and a valid new value.';return}const n=(Number(b)-Number(a))/Number(a)*100;$('#percentResult').textContent=`${Math.abs(n).toFixed(2)}% ${n<0?'decrease':n>0?'increase':'change'}`};$('#averageCalc').onclick=()=>{const raw=$('#averageValues').value.trim(),parts=raw.split(',').map(x=>x.trim()),values=parts.map(Number);if(!raw||parts.some(x=>!x)||values.some(x=>!Number.isFinite(x))){$('#averageResult').textContent='Enter valid comma-separated numbers.';return}$('#averageResult').textContent=`Mean: ${Number((values.reduce((a,b)=>a+b,0)/values.length).toPrecision(12))} · Count: ${values.length}`}}
function renderNotebook(){const saved=Q.filter(q=>state.bookmarks.includes(q.id)),date=todayLocal();app.innerHTML=heading('ANUSHKA’S NOTEBOOK','For the ideas worth keeping.','Your reflections, saved questions, and lesson notes, together.')+`<section class="panel"><div class="section-title"><h2>Today’s reflection</h2><span class="pill">${date}</span></div><textarea id="notebookDaily" placeholder="A reading summary, a breakthrough, a reminder to yourself…">${escapeHTML(state.notes['day:'+date]||'')}</textarea><button class="primary" id="saveNotebook" style="margin-top:14px">Save my thoughts ♡</button></section><section class="panel" style="margin-top:20px"><div class="section-title"><h2>Saved for another look (${saved.length})</h2></div>${saved.length?saved.map(q=>`<div class="task"><div><b>${q.subject.toUpperCase()} · ${escapeHTML(q.groupTitle||lessons.find(l=>l.id===q.topic)?.title||q.topic)}</b><p>${escapeHTML(q.text.slice(0,120))}</p></div><button class="text-button" data-open-saved="${q.id}">Try →</button><button class="text-button" data-remove-saved="${q.id}" aria-label="Remove saved question ${q.id}">×</button></div>`).join(''):'<p class="muted">Use ☆ Save while practicing to build your own revision collection.</p>'}</section><section class="panel" style="margin-top:20px"><div class="section-title"><h2>Your note collection</h2></div>${Object.entries(state.notes).filter(([k,v])=>v.trim()&&k!=='day:'+date).reverse().map(([k,v])=>`<details class="note-entry"><summary>${escapeHTML(k.startsWith('lesson:')?lessons.find(l=>l.id===k.slice(7))?.title||k:k.slice(4))}</summary><p style="white-space:pre-wrap">${escapeHTML(v)}</p></details>`).join('')||'<p class="muted">Lesson notes and past daily reflections appear here.</p>'}</section><div class="notice">Everything stays in this browser. Use My progress → Export data to keep a backup. You can restore a compatible export in My preferences.</div>`;$('#saveNotebook').onclick=()=>{state.notes['day:'+date]=$('#notebookDaily').value;save();toast('Saved. Future-you will appreciate it.')};document.querySelectorAll('[data-open-saved]').forEach(b=>b.onclick=()=>startQuestionList([Q.find(q=>q.id===Number(b.dataset.openSaved))]));document.querySelectorAll('[data-remove-saved]').forEach(b=>b.onclick=()=>{state.bookmarks=state.bookmarks.filter(x=>x!==Number(b.dataset.removeSaved));save();renderNotebook()})}
function renderReferences(){app.innerHTML=heading('ANUSHKA’S REFERENCE SHELF','A thoughtful shelf. A clearer direction.','Ten established starting points, with the official authority kept separate.')+`<div class="notice">These are established reference destinations, not a ranked “top ten”. Their current offerings have not been independently verified. All lessons, passages and questions on this website are original. No affiliation or endorsement is implied.</div><div class="lesson-grid">${referenceSites.map((r,i)=>`<article class="lesson-card reference-card"><span class="pill">${String(i+1).padStart(2,'0')} · ${r.kind}</span><h3>${r.name}</h3><p>${r.focus}</p><a href="${r.url}" target="_blank" rel="noopener noreferrer" class="secondary">Visit official site ↗</a></article>`).join('')}</div><section class="panel article" style="margin-top:22px"><h3>How to use references without scattering your prep</h3><ol><li>Use the official CAT notification for dates, eligibility, registration and scoring.</li><li>Pick a primary learning method and avoid collecting overlapping subscriptions.</li><li>Supplement the original bank here with advanced sets and independently calibrated mocks as needed.</li><li>Keep all mock-analysis actions and daily reflections in this website’s notebook.</li><li>When comparing a course, verify current content, access duration, refund terms and total cost directly.</li></ol></section>`}
function renderPreferences(){app.innerHTML=heading('YOUR SPACE, YOUR WAY','Made for Anushka. Shaped by you.','A few small preferences to make the plan feel more like yours.')+`<section class="panel"><div class="form-row"><div class="field"><label for="preferredName">Preferred name</label><input id="preferredName" maxlength="40" value="${escapeHTML(state.profile.name)}"></div><div class="field"><label for="targetYear">CAT exam year</label><input id="targetYear" readonly type="number" min="2026" max="2040" placeholder="Choose when you know" value="${escapeHTML(state.profile.year||'')}"></div><button class="primary" id="savePreferences">Save my preferences</button></div><p class="muted">Your exam is set to 29 November 2026. Adjust your available study time in Study planner.</p></section><section class="panel" style="margin-top:20px"><div class="section-title"><h2>Keep a backup. Bring it back.</h2></div><p class="muted">Export includes your notes, attempts, study plan, preferences and timer. Import replaces the current local progress after confirmation. Keep files private if your notes contain personal information.</p><div class="quiz-actions"><button class="secondary" id="backupData">Export my data ↓</button><label class="secondary" style="cursor:pointer">Restore a backup <input type="file" accept="application/json,.json" id="restoreData" hidden></label></div><p class="muted" id="restoreStatus" role="status"></p></section><div class="notice">Personalized does not mean access-restricted. Anyone who can access the site can see its learning content and Anushka’s name. Her browser progress and notes are local. This static site does not provide password protection, a private account, or cross-device sync.</div>`;$('#savePreferences').onclick=()=>{const name=$('#preferredName').value.trim(),year=$('#targetYear').value;if(!name){toast('Add a name to make the space yours.');return}if(year&&(!Number.isInteger(Number(year))||Number(year)<2026||Number(year)>2040)){toast('Choose a year between 2026 and 2040, or leave it blank.');return}state.profile.name=name;state.profile.year='2026';save();$('.profile b').textContent=name+'’s CAT journey';toast('Saved. This is your space, '+name+'.')};$('#backupData').onclick=()=>download('anushka-catalyst-backup.json',JSON.stringify(state,null,2));$('#restoreData').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>5*1024*1024)throw Error('Use a backup smaller than 5 MB.');const data=JSON.parse(await f.text());if(!Array.isArray(data.attempts)||!Array.isArray(data.completed)||!Array.isArray(data.results)||data.attempts.some(x=>!x||!Number.isInteger(x.id)||typeof x.correct!=='boolean'||!Number.isFinite(x.time))||data.completed.some(x=>typeof x!=='string')||data.profile&&typeof data.profile.name!=='string')throw Error('This file is not a compatible CATalyst backup.');const object=x=>x&&typeof x==='object'&&!Array.isArray(x);const validDate=x=>typeof x==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(x)&&!Number.isNaN(new Date(x+'T12:00:00').getTime());
if(data.profile&&(!object(data.profile)||data.profile.name.length>40||!/^([01]\d|2[0-3]):[0-5]\d$/.test(data.profile.startTime||'18:00')||!Number.isInteger(Number(data.profile.restDay??0))||Number(data.profile.restDay??0)<0||Number(data.profile.restDay??0)>6))throw Error('Invalid profile in backup.');
if(data.plan&&(!object(data.plan)||!validDate(data.plan.target)||data.plan.start&&!validDate(data.plan.start)||![60,90,120,150,180,240,300].includes(data.plan.minutes)||!Number.isFinite(data.plan.created)))throw Error('Invalid study plan in backup.');
for(const key of ['notes','confidence'])if(data[key]&&(!object(data[key])||Object.values(data[key]).some(x=>typeof x!=='string')))throw Error('Invalid notes or reflections in backup.');
for(const key of ['tasks','dailyTasks'])if(data[key]&&(!object(data[key])||Object.values(data[key]).some(x=>typeof x!=='boolean')))throw Error('Invalid tasks in backup.');
if(data.bookmarks&&(!Array.isArray(data.bookmarks)||data.bookmarks.some(x=>!Number.isInteger(x))))throw Error('Invalid saved questions in backup.');
if(!Number.isFinite(data.focus)||data.focus<0||data.results.some(r=>!object(r)||typeof r.title!=='string'||['time','correct','wrong','total','score'].some(k=>!Number.isFinite(r[k]))))throw Error('Invalid progress totals in backup.');
if(data.syllabus&&(!Array.isArray(data.syllabus)||data.syllabus.some(x=>typeof x!=='string')))throw Error('Invalid syllabus progress in backup.');if(data.earlierRoutineHistory&&(!Array.isArray(data.earlierRoutineHistory)||data.earlierRoutineHistory.some(x=>typeof x!=='string')))throw Error('Invalid earlier schedule in backup.');if(data.results.some(r=>r.review&&!validSavedReview(r.review)))throw Error('Invalid saved test review in backup.');if(data.reviewQueue&&(!object(data.reviewQueue)||Object.entries(data.reviewQueue).some(([id,x])=>!/^\d+$/.test(id)||!object(x)||![x.dueAt,x.lastAt,x.streak,x.intervalDays].every(Number.isFinite)||x.streak<0||x.intervalDays<1||typeof x.lastCorrect!=='boolean')))throw Error('Invalid revision schedule in backup.');if(data.previousStudyPlans&&!Array.isArray(data.previousStudyPlans))throw Error('Invalid previous study plans in backup.');if(!confirm('Replace this browser’s current progress with the selected backup? Export first if needed.'))return;const clean=JSON.parse(JSON.stringify(data));delete clean.__proto__;state={attempts:[],completed:[],results:[],tasks:{},plan:null,focus:0,...clean};state.profile={name:'Anushka',daily:120,startTime:'18:00',restDay:0,...state.profile};state.bookmarks??=[];state.notes??={};state.dailyTasks??={};state.confidence??={};state.mockLog??=[];state.syllabus??=[];alignPlanForExam();initialiseReviewQueue();state.studyClock={duration:1500,remaining:1500,running:false,end:null,label:'One focused step',kind:'study'};studyClock=state.studyClock;save();renderPreferences();toast('Backup restored. Welcome back.')}catch(error){$('#restoreStatus').textContent=error.message}}}
// More useful progress: topical weak spots, reflection categories, mock history, and a portable backup.
renderProgress=function(){const unique=new Set(state.attempts.map(a=>a.id)),errors=[...new Set(state.attempts.filter(a=>!a.correct).map(a=>a.id))],categories=Object.entries(state.confidence).reduce((out,[id,cause])=>{if(cause)out[cause]=(out[cause]||0)+1;return out},{});app.innerHTML=heading('ANUSHKA’S PROGRESS','Look at what you’re building.','Your own evidence of effort, and clues for what comes next.',`<button class="secondary" id="exportProgress">Export my data ↓</button>`)+`<div class="stats"><div class="stat"><div><b>${state.attempts.length}</b><p>Attempts · ${unique.size} unique questions</p></div></div><div class="stat"><div><b>${accuracy()}<small> %</small></b><p>Accuracy across attempts</p></div></div><div class="stat"><div><b>${state.completed.length}<small> / ${lessons.length}</small></b><p>Lessons marked learned</p></div></div><div class="stat"><div><b>${state.results.length}</b><p>Tests completed</p></div></div></div><section class="panel"><div class="section-title"><h2>A clearer view of each section</h2></div><div class="table-wrap"><table><thead><tr><th>Section</th><th>Attempts</th><th>Accuracy</th><th>Next little step</th></tr></thead><tbody>${subjects.map(s=>{const a=state.attempts.filter(x=>x.subject===s.id),percent=a.length?Math.round(a.filter(x=>x.correct).length/a.length*100):null;return `<tr><td>${s.name}</td><td>${a.length}</td><td>${percent===null?'Not started':percent+'%'}</td><td>${percent===null?'Try a diagnostic':percent<60?'Revisit foundations and work slowly':'Add timed practice and review guesses'}</td></tr>`}).join('')}</tbody></table></div></section><div class="lower-grid"><section class="panel"><div class="section-title"><h2>Your error notebook (${errors.length})</h2></div>${errors.length?errors.map(id=>{const q=Q.find(q=>q.id===id);if(!q)return '';const last=state.attempts.filter(a=>a.id===id).at(-1);return `<div class="task"><div><b>${q.subject.toUpperCase()} · ${lessons.find(l=>l.id===q.topic)?.title||q.topic}</b><p>${escapeHTML(state.confidence[id]||'Add a reflection after retrying')} · ${last.correct?'Latest attempt correct ✓':'Ready for another look'}</p></div><button class="text-button" data-retry="${id}">Retry →</button></div>`}).join(''):'<div class="empty"><h2>A fresh notebook.</h2><p>Missed questions will appear here. A mistake is information.</p><a href="#practice" class="primary">Start gently →</a></div>'}</section><section class="panel"><div class="section-title"><h2>Patterns worth noticing</h2></div>${Object.keys(categories).length?Object.entries(categories).map(([cause,n])=>`<div class="task"><b>${escapeHTML(cause)}</b><span class="pill" style="margin-left:auto">${n} questions</span></div>`).join(''):'<p class="muted">After checking an answer, label what happened: concept gap, misreading, calculation, time pressure, or a lucky guess. Your pattern summary appears here.</p>'}<div class="achievement">◷ ${state.focus} focus minutes · ${streak()}-day practice streak</div><p class="muted">Reflections show your latest label per question. Accuracy includes repeat attempts and does not predict a CAT percentile.</p></section></div><section class="panel" style="margin-top:22px"><div class="section-title"><h2>Your test timeline</h2></div>${state.results.length?`<div class="table-wrap"><table><thead><tr><th>Test</th><th>Date</th><th>Score</th><th>Correct</th><th>Attempted</th><th>Review</th></tr></thead><tbody>${[...state.results].reverse().map((r,index)=>`<tr><td>${escapeHTML(r.title)}</td><td>${r.sourceDate?escapeHTML(r.sourceDate):new Date(r.time).toLocaleDateString('en-IN')}</td><td>${r.score} / ${r.total*3}</td><td>${r.correct}</td><td>${r.correct+r.wrong}</td><td>${r.review?`<button class="text-button" data-review-result="${state.results.length-1-index}">Review answers →</button>`:'<span class="muted">Totals only</span>'}</td></tr>`).join('')}</tbody></table></div>`:'<p class="muted">Your first diagnostic or timed test will start the timeline.</p>'}</section><div class="notice">Progress stays in this browser. Export a backup before changing devices or clearing site data. Restore a backup in <a href="#settings">My preferences</a>.</div>`;$('#exportProgress').onclick=()=>download('anushka-catalyst-progress.json',JSON.stringify(state,null,2));document.querySelectorAll('[data-retry]').forEach(b=>b.onclick=()=>startQuestionList([Q.find(q=>q.id===Number(b.dataset.retry))]))};
renderRevision=function(){const l=lessons[cardIndex];app.innerHTML=heading('ANUSHKA’S QUICK REVISION','A small refresh. A stronger foundation.',`${lessons.length} concept cards. Say it first, then turn the card.`)+`<div class="flashcard"><span class="pill">${l.subject.toUpperCase()} · CARD ${cardIndex+1} OF ${lessons.length}</span><h2>${l.title}</h2><p>${cardBack?l.formula+'<br><br><b>Watch for:</b> '+l.trap:'Before you reveal it, explain the key idea in your own words.'}</p><button class="primary" id="flipCard">${cardBack?'Show prompt':'Reveal key ideas'} ↻</button></div><div class="flash-actions"><button class="secondary" id="prevCard">← Previous</button><button class="secondary" id="randomCard">Surprise me ✧</button><button class="secondary" id="nextCard">Next →</button></div>`;$('#flipCard').onclick=()=>{cardBack=!cardBack;renderRevision()};$('#prevCard').onclick=()=>{cardIndex=(cardIndex+lessons.length-1)%lessons.length;cardBack=false;renderRevision()};$('#nextCard').onclick=()=>{cardIndex=(cardIndex+1)%lessons.length;cardBack=false;renderRevision()};$('#randomCard').onclick=()=>{cardIndex=Math.floor(Math.random()*lessons.length);cardBack=false;renderRevision()}};
// Keep the original exam guidance, with the expanded reference shelf linked alongside it.
renderGuide=function(){oldGuide();$('.page-heading h1').textContent='Anushka, see the whole journey.';app.insertAdjacentHTML('beforeend','<div class="bottom-banner"><span>↗</span><div><b>Your combined reference shelf</b><p>Keep official rules separate from independent learning resources.</p></div><a href="#references">Open shelf →</a></div>')};
const routeTitles={dashboard:'Your space',learn:'Learning library',practice:'Practice arena',tests:'Test room',planner:'Study planner',schedule:'Daily schedule',timer:'Study timer',calculator:'Calculator',notebook:'My notebook',references:'Reference shelf',settings:'My preferences',revision:'Revision cards',progress:'My progress',guide:'Exam guide'};
route=function(){const [rawPage,filter]=location.hash.slice(1).split('/');const page=rawPage||'dashboard';if(quiz?.mode==='test'){history.replaceState(null,'','#tests');toast('Your test is still running. Finish or submit it before leaving.');renderQuiz();return}quiz=null;clearInterval(quizTimer);document.querySelectorAll('[data-nav]').forEach(a=>a.classList.toggle('active',a.dataset.nav===page));$('.sidebar').classList.remove('open');$('#menu').setAttribute('aria-expanded','false');$('#breadcrumb').innerHTML=`${person()}’s workspace <span>/</span> ${routeTitles[page]||'Your space'}`;({dashboard:renderDashboard,learn:()=>renderLearn(filter),practice:renderPractice,tests:renderTests,planner:renderPlanner,schedule:renderSchedule,timer:renderStudyTimer,calculator:renderCalculator,notebook:renderNotebook,references:renderReferences,settings:renderPreferences,revision:renderRevision,progress:renderProgress,guide:renderGuide,papers:renderSamplePapers,sectionals:renderSectionalCatalog,syllabus:renderSyllabus,review:renderReviewHub,coverage:renderCoverage}[page]||renderDashboard)();window.scrollTo(0,0)};
