window.addEventListener('hashchange',route);
initializeUniverse();
initializeLearningAudit();
initializeExamPlan();
try{const stored=sessionStorage.getItem('catalyst-active-test');if(stored){const data=JSON.parse(stored);if(data.mode==='test'&&Array.isArray(data.questions)&&data.questions.length&&Number.isFinite(data.ends)){quiz=data;clearInterval(quizTimer);quizTimer=setInterval(updateTestTimer,1000);toast('Your unfinished test has resumed in this tab.')}}}catch{}
$('.profile b').textContent=state.profile.name+'’s CAT journey';
$('footer').innerHTML='Made for Anushka, one day at a time. <span>Your next chapter is worth it. ♡</span>';
if(quiz?.mode==='test')renderQuiz();else route();

